// Assembles www/:
//   1. build front (the shared Vue app)
//   2. copy its dist into www/
//   3. build the app (app/) into www/capacitor-app.js
//   4. swap front's module script in index.html for capacitor-app.js
//
// Step 4 lets the app load front itself once its routes are registered, so Invoke.js never
// calls IPC too early. front's index.html is generated by its own build, so patching it here
// keeps the two repos independent.
//
// --release builds front with its .env.release (production URLs). Without it front is
// built with its local .env.

import { execSync } from 'node:child_process';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import fs from 'fs-extra';
import { injectApp } from './inject.mjs';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const www = resolve(root, 'www');
const front_dist = resolve(root, '../front/dist');
const is_release = process.argv.includes('--release');

function run(command) {
    execSync(command, { cwd: root, stdio: 'inherit' });
}

run(is_release ? 'npm run build:front:release' : 'npm run build:front');

await fs.emptyDir(www);
await fs.copy(front_dist, www);

run('npm run build:app');

if ( injectApp(www) ) {
    console.log('[build] injected capacitor-app.js');
}
else {
    console.log('[build] app already injected');
}
